    quality?: QualitySetting;
    /** Suspend updates and drawing while keeping the native surface mounted. */
    paused?: boolean;
    style?: ViewStyle;
    /** A quick tap, at \`x, y\` points in the view. \`world.pick(x, y)\` finds what was tapped. */
